// @ts-nocheck
'use client'

import dynamic from 'next/dynamic'
import { useState, useEffect, useRef } from 'react'

const DynamicCanvas = dynamic(
  () => import('./Canvas3D'),
  { ssr: false, loading: () => <div className="h-[60vh] bg-zinc-900 flex items-center justify-center text-zinc-400">Loading 3D...</div> }
)

export default function SetupPage() {
  const [carState, setCarState] = useState<'off' | 'idle' | 'moving'>('idle')
  const [doorsOpen, setDoorsOpen] = useState(false)

  return (
    <div className="min-h-screen bg-zinc-950">
      <div className="container mx-auto px-6 py-8">
        <h1 className="text-4xl font-bold text-zinc-100 mb-2">Setup</h1>
        <p className="text-zinc-400 mb-8">2022 Toyota GR86</p>

        <div className="flex flex-wrap gap-4 mb-8">
          <div className="flex gap-2">
            <button
              onClick={() => setCarState('off')}
              className={`px-4 py-2 rounded-lg text-sm font-medium transition-colors ${
                carState === 'off' ? 'bg-zinc-100 text-zinc-900' : 'bg-zinc-800 text-zinc-400 hover:bg-zinc-700'
              }`}
            >
              Engine Off
            </button>
            <button
              onClick={() => setCarState('idle')}
              className={`px-4 py-2 rounded-lg text-sm font-medium transition-colors ${
                carState === 'idle' ? 'bg-zinc-100 text-zinc-900' : 'bg-zinc-800 text-zinc-400 hover:bg-zinc-700'
              }`}
            >
              Idle
            </button>
            <button
              onClick={() => setCarState('moving')}
              className={`px-4 py-2 rounded-lg text-sm font-medium transition-colors ${
                carState === 'moving' ? 'bg-zinc-100 text-zinc-900' : 'bg-zinc-800 text-zinc-400 hover:bg-zinc-700'
              }`}
            >
              Moving
            </button>
          </div>

          <button
            onClick={() => setDoorsOpen(!doorsOpen)}
            className={`px-4 py-2 rounded-lg text-sm font-medium transition-colors ${
              doorsOpen ? 'bg-blue-600 text-white' : 'bg-zinc-800 text-zinc-400 hover:bg-zinc-700'
            }`}
          >
            {doorsOpen ? 'Close Doors' : 'Open Doors'}
          </button>
        </div>

        <div className="text-zinc-500 text-sm mb-4">
          Drag to rotate | Scroll to zoom
        </div>
      </div>

      <DynamicCanvas doorsOpen={doorsOpen} carState={carState} />

      <div className="container mx-auto px-6 py-8">
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          <div className="bg-zinc-900/50 rounded-lg p-4">
            <h3 className="text-zinc-100 font-medium mb-2">Engine States</h3>
            <p className="text-zinc-400 text-sm">
              {carState === 'off' && 'Engine is off - no vibration'}
              {carState === 'idle' && 'Engine running - subtle rumble vibration'}
              {carState === 'moving' && 'Engine revving - gentle bobbing motion'}
            </p>
          </div>
          <div className="bg-zinc-900/50 rounded-lg p-4">
            <h3 className="text-zinc-100 font-medium mb-2">Doors</h3>
            <p className="text-zinc-400 text-sm">
              Click "Open Doors" to swing both doors open
            </p>
          </div>
          <div className="bg-zinc-900/50 rounded-lg p-4">
            <h3 className="text-zinc-100 font-medium mb-2">Controls</h3>
            <p className="text-zinc-400 text-sm">
              Drag to rotate view | Scroll to zoom
            </p>
          </div>
        </div>
      </div>
    </div>
  )
}
